-- 008: third-party open-source tools (verified repo and license from the GitHub API on 2026-11-25). Each row credits the original creator and links to the original repository.
insert into public.tools (slug, name, class, description_en, description_ar, commands, visibility, status, created_by, third_party, orig_creator, orig_license, orig_repo)
select v.slug, v.name, v.cls, v.en, v.ar, v.cmds, 'public', 'published', (select id from public.profiles where role = 'owner' limit 1), true, v.creator, v.lic, v.repo
from (values
  ($q$masscan$q$, $q$Masscan$q$, $q$recon$q$, $q$Very fast TCP port scanner that can sweep large ranges. Give it targets with a port list and a packet rate, and save results as JSON or a list. Keep the rate low on shared networks. Use it only on systems you own or have written permission to test.$q$, $q$ماسح بورتات TCP سريع جدا بيفحص نطاقات كبيرة. بتديله الأهداف والبورتات ومعدل الإرسال، وبيحفظ النتيجة JSON أو قائمة. خلي المعدل واطي على الشبكات المشتركة. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$masscan 10.0.0.0/24 -p80,443 --rate 1000$q$, $q$masscan 192.168.1.0/24 -p0-1000 -oJ out.json$q$, $q$masscan 10.0.0.0/16 -p22 --excludefile exclude.txt$q$]::text[], $q$Robert David Graham$q$, $q$AGPL-3.0$q$, $q$https://github.com/robertdavidgraham/masscan$q$),
  ($q$subfinder$q$, $q$Subfinder$q$, $q$recon$q$, $q$Passive subdomain discovery from public sources. Run it on a domain and pipe the list into httpx or Nuclei. API keys for some sources improve results.$q$, $q$اكتشاف subdomains سلبي من مصادر عامة. بتشغله على دومين وتمرر القائمة لـ httpx أو Nuclei. مفاتيح API لبعض المصادر بتحسّن النتيجة.$q$, array[$q$subfinder -d example.com$q$, $q$subfinder -d example.com -silent -o subs.txt$q$, $q$subfinder -dL domains.txt -all$q$]::text[], $q$ProjectDiscovery$q$, $q$MIT$q$, $q$https://github.com/projectdiscovery/subfinder$q$),
  ($q$httpx$q$, $q$httpx$q$, $q$recon$q$, $q$Fast HTTP probe. Takes a list of hosts and shows which are alive, with status code, page title and detected technology.$q$, $q$فاحص HTTP سريع. بياخد قائمة هوستات ويقولك مين شغال، مع status code وعنوان الصفحة والتقنيات.$q$, array[$q$httpx -l subs.txt -status-code -title$q$, $q$echo example.com | httpx -tech-detect$q$, $q$httpx -l subs.txt -silent -o live.txt$q$]::text[], $q$ProjectDiscovery$q$, $q$MIT$q$, $q$https://github.com/projectdiscovery/httpx$q$),
  ($q$ffuf$q$, $q$ffuf$q$, $q$recon$q$, $q$Fast web fuzzer. Replace the word FUZZ in a URL, header or body with entries from a wordlist to find hidden paths, files and parameters. Filter noise by status code or size. Use it only on systems you own or have written permission to test.$q$, $q$Fuzzer سريع للويب. بتحط الكلمة FUZZ في الرابط أو الهيدر وبيجرب قائمة كلمات عشان يلاقي مسارات وملفات وباراميترات مخفية. فلتر الضوضاء بالـ status أو الحجم. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$ffuf -u https://example.com/FUZZ -w wordlist.txt$q$, $q$ffuf -u https://example.com/FUZZ -w wordlist.txt -mc 200,301$q$, $q$ffuf -u https://example.com/FUZZ -w wordlist.txt -fs 1234$q$]::text[], $q$The ffuf project$q$, $q$MIT$q$, $q$https://github.com/ffuf/ffuf$q$),
  ($q$gobuster$q$, $q$Gobuster$q$, $q$recon$q$, $q$Brute-forces directories, files and DNS subdomains from a wordlist. Choose a mode (dir or dns), give the target and a wordlist. Use it only on systems you own or have written permission to test.$q$, $q$بيجرب مجلدات وملفات وsubdomains من قائمة كلمات. بتختار الوضع (dir أو dns) وتديله الهدف والقائمة. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$gobuster dir -u https://example.com -w wordlist.txt$q$, $q$gobuster dns -d example.com -w subs.txt$q$]::text[], $q$OJ Reeves$q$, $q$Apache-2.0$q$, $q$https://github.com/OJ/gobuster$q$),
  ($q$recon-ng$q$, $q$Recon-ng$q$, $q$recon$q$, $q$Web reconnaissance framework with a Metasploit-like console. Create a workspace, install modules from the marketplace, set a source and run.$q$, $q$إطار recon للويب بشكل شبه Metasploit. بتعمل workspace وتنزل modules من الـ marketplace وتحدد المصدر وتشغل.$q$, array[$q$recon-ng$q$, $q$marketplace install all$q$, $q$workspaces create demo$q$, $q$modules load recon/domains-hosts/hackertarget$q$, $q$options set SOURCE example.com$q$, $q$run$q$]::text[], $q$Tim Tomes (lanmaster53)$q$, $q$GPL-3.0$q$, $q$https://github.com/lanmaster53/recon-ng$q$),
  ($q$whatweb$q$, $q$WhatWeb$q$, $q$recon$q$, $q$Identifies the technologies a website uses: CMS, frameworks, servers and plugins. Aggression level 1 is light, level 3 is deeper. Use it only on systems you own or have written permission to test.$q$, $q$بيعرّف التقنيات اللي الموقع بيستخدمها: CMS وframeworks وسيرفرات وplugins. مستوى 1 خفيف ومستوى 3 أعمق. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$whatweb example.com$q$, $q$whatweb -a 3 example.com$q$, $q$whatweb --log-json=out.json example.com$q$]::text[], $q$Andrew Horton (urbanadventurer)$q$, $q$GPL-2.0$q$, $q$https://github.com/urbanadventurer/WhatWeb$q$),
  ($q$spiderfoot$q$, $q$SpiderFoot$q$, $q$recon$q$, $q$OSINT automation. Start the web interface or run a scan from the command line against a domain, IP or name, and review collected findings.$q$, $q$أتمتة OSINT. بتشغل الواجهة أو سكان من سطر الأوامر على دومين أو IP أو اسم وتراجع النتائج.$q$, array[$q$python3 sf.py -l 127.0.0.1:5001$q$, $q$python3 sf.py -s example.com -u passive$q$]::text[], $q$Steve Micallef$q$, $q$MIT$q$, $q$https://github.com/smicallef/spiderfoot$q$),
  ($q$sherlock$q$, $q$Sherlock$q$, $q$recon$q$, $q$Looks for a username across many social networks and sites. Useful for OSINT on handles you are allowed to research.$q$, $q$بيدور على يوزرنيم في مواقع تواصل كتير. مفيد في OSINT على حسابات مسموح لك تبحث عنها.$q$, array[$q$sherlock username$q$, $q$sherlock user1 user2$q$, $q$sherlock username --timeout 10$q$]::text[], $q$Sherlock Project$q$, $q$MIT$q$, $q$https://github.com/sherlock-project/sherlock$q$),
  ($q$naabu$q$, $q$Naabu$q$, $q$recon$q$, $q$Fast port scanner from ProjectDiscovery. Scan a host, a list, or the top ports, and pass results to httpx or Nmap. Use it only on systems you own or have written permission to test.$q$, $q$ماسح بورتات سريع من ProjectDiscovery. بتفحص هوست أو قائمة أو أشهر البورتات وتمرر النتيجة لـ httpx أو Nmap. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$naabu -host example.com$q$, $q$naabu -list hosts.txt -top-ports 100$q$, $q$naabu -host example.com -p 80,443$q$]::text[], $q$ProjectDiscovery$q$, $q$MIT$q$, $q$https://github.com/projectdiscovery/naabu$q$),
  ($q$metasploit-framework$q$, $q$Metasploit Framework$q$, $q$pentest$q$, $q$Penetration testing framework with exploits, payloads and auxiliary modules. Search a module, load it, set the options (RHOSTS), check, then run. Use it only on systems you own or have written permission to test.$q$, $q$إطار اختبار اختراق فيه exploits وpayloads وmodules مساعدة. بتدور على module وتحمله وتظبط الاعدادات (RHOSTS) وتعمل check وبعدين run. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$msfconsole$q$, $q$search type:exploit name:smb$q$, $q$use <module path>$q$, $q$show options$q$, $q$set RHOSTS 10.0.0.5$q$, $q$check$q$, $q$run$q$]::text[], $q$Rapid7 and the Metasploit community$q$, $q$BSD-3-Clause$q$, $q$https://github.com/rapid7/metasploit-framework$q$),
  ($q$sqlmap$q$, $q$sqlmap$q$, $q$pentest$q$, $q$Automatic SQL injection detection and exploitation. Point it at a URL with a parameter, list databases, then tables. Start with low risk and level. Use it only on systems you own or have written permission to test.$q$, $q$اكتشاف واستغلال SQL injection تلقائي. بتديله رابط فيه باراميتر وبيعرض الـ databases وبعدين الجداول. ابدأ بمستوى ومخاطرة واطيين. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$sqlmap -u "http://target/page.php?id=1" --batch$q$, $q$sqlmap -u "http://target/page.php?id=1" --dbs$q$, $q$sqlmap -u "http://target/page.php?id=1" -D db --tables$q$, $q$sqlmap -u "http://target/page.php?id=1" --level 1 --risk 1$q$]::text[], $q$sqlmap developers (Bernardo Damele and Miroslav Stampar)$q$, $q$GPL with extra terms (see repo)$q$, $q$https://github.com/sqlmapproject/sqlmap$q$),
  ($q$nikto$q$, $q$Nikto$q$, $q$pentest$q$, $q$Web server scanner that checks for dangerous files, outdated software and misconfigurations. Noisy, so only run it with permission. Use it only on systems you own or have written permission to test.$q$, $q$سكانر لسيرفرات الويب بيدور على ملفات خطيرة وبرامج قديمة واعدادات غلط. صوته عالي فاستخدمه بإذن بس. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$nikto -h https://example.com$q$, $q$nikto -h example.com -p 80,443$q$, $q$nikto -h example.com -o report.html -Format htm$q$]::text[], $q$Chris Sullo$q$, $q$Custom license (see COPYING in repo)$q$, $q$https://github.com/sullo/nikto$q$),
  ($q$john-the-ripper$q$, $q$John the Ripper$q$, $q$pentest$q$, $q$Password hash cracker with many formats. Run it with a wordlist on a hash file, then show cracked passwords. Use only on hashes you are allowed to test. Use it only on systems you own or have written permission to test.$q$, $q$كاسر هاشات باسوردات بصيغ كتير. بتشغله بقائمة كلمات على ملف هاشات وبعدين تعرض اللي اتكسر. استخدمه على هاشات مسموح لك بيها. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$john --wordlist=wordlist.txt hashes.txt$q$, $q$john --show hashes.txt$q$, $q$john --list=formats$q$, $q$john --format=raw-md5 hashes.txt$q$]::text[], $q$Solar Designer and Openwall$q$, $q$GPL with extra terms (see repo)$q$, $q$https://github.com/openwall/john$q$),
  ($q$thc-hydra$q$, $q$THC Hydra$q$, $q$pentest$q$, $q$Online login brute-forcer for SSH, FTP, HTTP forms and many more services. Use low thread counts and only on accounts you own or are allowed to test. Use it only on systems you own or have written permission to test.$q$, $q$بيجرب باسوردات أونلاين على SSH وFTP وفورمز HTTP وخدمات تانية. استخدم threads قليلة وعلى حسابات بتاعتك أو مسموح لك بيها. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$hydra -l admin -P pass.txt ssh://10.0.0.5$q$, $q$hydra -L users.txt -P pass.txt 10.0.0.5 ftp$q$, $q$hydra -t 4 -l admin -P pass.txt ssh://10.0.0.5$q$]::text[], $q$van Hauser (THC)$q$, $q$AGPL-3.0$q$, $q$https://github.com/vanhauser-thc/thc-hydra$q$),
  ($q$responder$q$, $q$Responder$q$, $q$pentest$q$, $q$LLMNR, NBT-NS and mDNS poisoner for internal network tests. Use analyze mode first to only watch traffic. Use it only on systems you own or have written permission to test.$q$, $q$بيعمل poisoning لـ LLMNR وNBT-NS وmDNS في اختبارات الشبكة الداخلية. ابدأ بوضع analyze عشان تراقب بس. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$sudo responder -I eth0 -A$q$, $q$sudo responder -I eth0$q$]::text[], $q$Laurent Gaffie$q$, $q$GPL-3.0$q$, $q$https://github.com/lgandx/Responder$q$),
  ($q$impacket$q$, $q$Impacket$q$, $q$pentest$q$, $q$Python classes and scripts for working with Windows network protocols: SMB, Kerberos, MSRPC and more. Used for authorised Active Directory testing. Use it only on systems you own or have written permission to test.$q$, $q$مكتبة وسكريبتات بايثون للتعامل مع بروتوكولات ويندوز: SMB وKerberos وMSRPC. بتتستخدم في اختبار Active Directory المصرّح بيه. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$impacket-secretsdump DOMAIN/user@host$q$, $q$impacket-psexec DOMAIN/user@host$q$, $q$impacket-GetUserSPNs DOMAIN/user -dc-ip 10.0.0.1 -request$q$]::text[], $q$Fortra (originally SecureAuth)$q$, $q$Modified Apache license (see repo)$q$, $q$https://github.com/fortra/impacket$q$),
  ($q$bloodhound$q$, $q$BloodHound$q$, $q$pentest$q$, $q$Maps attack paths in Active Directory as a graph. Collect data with a collector, upload the ZIP, then run the built-in queries. Use it only on systems you own or have written permission to test.$q$, $q$بيرسم مسارات الهجوم في Active Directory كـ graph. بتجمع بيانات بـ collector وترفع الـ ZIP وتشغل الـ queries الجاهزة. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$SharpHound.exe -c All$q$, $q$Upload the ZIP in the BloodHound web UI$q$, $q$Run the pre-built Cypher queries$q$]::text[], $q$SpecterOps$q$, $q$Apache-2.0$q$, $q$https://github.com/SpecterOps/BloodHound$q$),
  ($q$netexec$q$, $q$NetExec$q$, $q$pentest$q$, $q$Network service enumeration and credential testing for SMB, SSH, WinRM and more. Successor of CrackMapExec. Use it only on systems you own or have written permission to test.$q$, $q$بيعمل enumeration لخدمات الشبكة واختبار credentials لـ SMB وSSH وWinRM. خليفة CrackMapExec. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$nxc smb 10.0.0.0/24$q$, $q$nxc smb 10.0.0.5 -u user -p pass --shares$q$, $q$nxc ssh 10.0.0.5 -u user -p pass$q$]::text[], $q$The NetExec project$q$, $q$BSD-2-Clause$q$, $q$https://github.com/Pennyw0rth/NetExec$q$),
  ($q$aircrack-ng$q$, $q$Aircrack-ng$q$, $q$pentest$q$, $q$Wi-Fi security suite: monitor mode, packet capture and WPA key testing. Use only on networks you own. Use it only on systems you own or have written permission to test.$q$, $q$مجموعة أدوات أمان Wi-Fi: monitor mode والتقاط الباكيتات واختبار مفاتيح WPA. على شبكات بتاعتك بس. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$airmon-ng start wlan0$q$, $q$airodump-ng wlan0mon$q$, $q$aircrack-ng -w wordlist.txt capture.cap$q$]::text[], $q$Thomas d'Otreppe and the Aircrack-ng team$q$, $q$GPL-2.0$q$, $q$https://github.com/aircrack-ng/aircrack-ng$q$),
  ($q$bettercap$q$, $q$Bettercap$q$, $q$pentest$q$, $q$Network attack and monitoring framework with an interactive console. Probe the local network and list hosts. Only on networks you own. Use it only on systems you own or have written permission to test.$q$, $q$إطار هجوم ومراقبة للشبكة بكونسول تفاعلي. بيستكشف الشبكة المحلية ويعرض الأجهزة. على شبكات بتاعتك بس. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$sudo bettercap -iface eth0$q$, $q$net.probe on$q$, $q$net.show$q$]::text[], $q$Simone Margaritelli (evilsocket)$q$, $q$GPL-3.0$q$, $q$https://github.com/bettercap/bettercap$q$),
  ($q$feroxbuster$q$, $q$Feroxbuster$q$, $q$pentest$q$, $q$Fast recursive content discovery written in Rust. Finds hidden folders and files, with extensions and thread control. Use it only on systems you own or have written permission to test.$q$, $q$اكتشاف محتوى متكرر وسريع بلغة Rust. بيلاقي مجلدات وملفات مخفية مع امتدادات وتحكم في threads. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$feroxbuster -u https://example.com$q$, $q$feroxbuster -u https://example.com -w wordlist.txt -x php,html$q$, $q$feroxbuster -u https://example.com -t 20$q$]::text[], $q$Ben Risher (epi052)$q$, $q$MIT$q$, $q$https://github.com/epi052/feroxbuster$q$),
  ($q$zeek$q$, $q$Zeek$q$, $q$forensics$q$, $q$Network analysis framework that turns traffic or a PCAP into structured logs (conn, dns, http, ssl). Good for investigations and hunting.$q$, $q$إطار تحليل شبكة بيحوّل الترافيك أو ملف PCAP للوجات منظمة (conn وdns وhttp وssl). كويس للتحقيق والـ hunting.$q$, array[$q$zeek -r capture.pcap$q$, $q$zeek -i eth0$q$, $q$cat conn.log | zeek-cut id.orig_h id.resp_h$q$]::text[], $q$The Zeek Project$q$, $q$BSD-style (3-clause)$q$, $q$https://github.com/zeek/zeek$q$),
  ($q$suricata$q$, $q$Suricata$q$, $q$defense$q$, $q$Network IDS, IPS and monitoring engine. Run it live on an interface or on a PCAP and read alerts from the logs. Update rules with suricata-update.$q$, $q$محرك IDS وIPS ومراقبة للشبكة. بتشغله على كارت شبكة أو PCAP وتقرا التنبيهات من اللوجات. حدّث القواعد بـ suricata-update.$q$, array[$q$suricata -c /etc/suricata/suricata.yaml -i eth0$q$, $q$suricata -c /etc/suricata/suricata.yaml -r capture.pcap$q$, $q$suricata-update$q$, $q$tail -f /var/log/suricata/fast.log$q$]::text[], $q$OISF (Open Information Security Foundation)$q$, $q$GPL-2.0$q$, $q$https://github.com/OISF/suricata$q$),
  ($q$velociraptor$q$, $q$Velociraptor$q$, $q$forensics$q$, $q$Endpoint monitoring, digital forensics and incident response. Collect artifacts from many machines and hunt across them from one server.$q$, $q$مراقبة endpoints وفورنزكس واستجابة للحوادث. بتجمع artifacts من أجهزة كتير وتعمل hunting من سيرفر واحد.$q$, array[$q$velociraptor config generate -i$q$, $q$velociraptor gui$q$, $q$velociraptor artifacts list$q$]::text[], $q$Velocidex (Rapid7)$q$, $q$AGPL-3.0$q$, $q$https://github.com/Velocidex/velociraptor$q$),
  ($q$plaso$q$, $q$Plaso$q$, $q$forensics$q$, $q$Builds a super timeline from disk images and logs. Create a .plaso file with log2timeline, then sort and export it.$q$, $q$بيعمل super timeline من صور الديسك واللوجات. بتعمل ملف .plaso بـ log2timeline وبعدين ترتبه وتصدره.$q$, array[$q$log2timeline.py timeline.plaso /evidence/image.dd$q$, $q$psort.py -o dynamic -w timeline.csv timeline.plaso$q$, $q$pinfo.py timeline.plaso$q$]::text[], $q$The Plaso project (log2timeline)$q$, $q$Apache-2.0$q$, $q$https://github.com/log2timeline/plaso$q$),
  ($q$binwalk$q$, $q$Binwalk$q$, $q$forensics$q$, $q$Firmware analysis tool. Scans a firmware image for embedded files and file systems, extracts them and shows entropy.$q$, $q$أداة تحليل firmware. بتفحص صورة الـ firmware وبتلاقي ملفات وأنظمة ملفات مدفونة وتستخرجها وتعرض الـ entropy.$q$, array[$q$binwalk firmware.bin$q$, $q$binwalk -e firmware.bin$q$, $q$binwalk -E firmware.bin$q$]::text[], $q$ReFirmLabs$q$, $q$MIT$q$, $q$https://github.com/ReFirmLabs/binwalk$q$),
  ($q$radare2$q$, $q$radare2$q$, $q$crypto$q$, $q$Reverse engineering framework with a command line disassembler, debugger and binary tools. Open a binary, analyse it and print functions.$q$, $q$إطار reverse engineering بـ disassembler وdebugger وأدوات للـ binaries من سطر الأوامر. بتفتح binary وتحلله وتطبع الدوال.$q$, array[$q$r2 -A binary$q$, $q$afl$q$, $q$pdf @ main$q$, $q$iz$q$]::text[], $q$pancake and the radare2 community$q$, $q$LGPL-3.0 (mostly, see COPYING.md)$q$, $q$https://github.com/radareorg/radare2$q$),
  ($q$cutter$q$, $q$Cutter$q$, $q$crypto$q$, $q$Free reverse engineering platform with a graphical interface, powered by Rizin. Good for disassembly, graphs and decompiling.$q$, $q$منصة reverse engineering مجانية بواجهة رسومية بتشتغل بـ Rizin. كويسة للـ disassembly والـ graphs والـ decompile.$q$, array[$q$cutter binary$q$]::text[], $q$Rizin organization$q$, $q$GPL-3.0$q$, $q$https://github.com/rizinorg/cutter$q$),
  ($q$wazuh$q$, $q$Wazuh$q$, $q$defense$q$, $q$Open-source security platform for threat detection, integrity monitoring and compliance. Agents report to a manager that raises alerts.$q$, $q$منصة أمان مفتوحة المصدر لاكتشاف التهديدات ومراقبة سلامة الملفات والامتثال. الـ agents بتبعت للـ manager اللي بيطلع التنبيهات.$q$, array[$q$systemctl status wazuh-manager$q$, $q$/var/ossec/bin/agent_control -l$q$, $q$tail -f /var/ossec/logs/alerts/alerts.json$q$]::text[], $q$Wazuh Inc.$q$, $q$Two licenses, see LICENSE in the repo$q$, $q$https://github.com/wazuh/wazuh$q$),
  ($q$snort-3$q$, $q$Snort 3$q$, $q$defense$q$, $q$Network intrusion detection and prevention system. Run it on a PCAP or live traffic with a config and rules, and print alerts.$q$, $q$نظام كشف ومنع اختراق للشبكة. بتشغله على PCAP أو ترافيك مباشر بملف اعدادات وقواعد وبيطبع التنبيهات.$q$, array[$q$snort -c /etc/snort/snort.lua -r capture.pcap -A alert_fast$q$, $q$snort -c /etc/snort/snort.lua -i eth0$q$]::text[], $q$Snort team (Cisco Talos)$q$, $q$GPL-2.0$q$, $q$https://github.com/snort3/snort3$q$),
  ($q$fail2ban$q$, $q$Fail2ban$q$, $q$defense$q$, $q$Bans IP addresses that show malicious behaviour such as repeated failed logins, by reading logs and adding firewall rules.$q$, $q$بيحظر عناوين IP اللي بتعمل سلوك مشبوه زي محاولات دخول فاشلة كتير، بقراءة اللوجات وإضافة قواعد firewall.$q$, array[$q$fail2ban-client status$q$, $q$fail2ban-client status sshd$q$, $q$fail2ban-client set sshd unbanip 1.2.3.4$q$]::text[], $q$Cyril Jaquier and contributors$q$, $q$GPL-2.0$q$, $q$https://github.com/fail2ban/fail2ban$q$),
  ($q$clamav$q$, $q$ClamAV$q$, $q$defense$q$, $q$Open-source antivirus engine. Update signatures with freshclam, then scan folders and list only infected files.$q$, $q$محرك مضاد فيروسات مفتوح المصدر. حدّث التوقيعات بـ freshclam وبعدين افحص مجلدات واعرض الملفات المصابة بس.$q$, array[$q$freshclam$q$, $q$clamscan -r /home$q$, $q$clamscan -r --infected /var/www$q$]::text[], $q$Cisco Talos$q$, $q$GPL-2.0$q$, $q$https://github.com/Cisco-Talos/clamav$q$),
  ($q$falco$q$, $q$Falco$q$, $q$defense$q$, $q$Runtime security for Linux hosts and containers. Watches system calls and alerts on suspicious behaviour using rules.$q$, $q$أمان runtime لسيرفرات لينكس والـ containers. بيراقب system calls وبيطلع تنبيه على سلوك مشبوه حسب القواعد.$q$, array[$q$falco$q$, $q$falco -r rules.yaml$q$, $q$falco --list$q$]::text[], $q$Falco community (CNCF)$q$, $q$Apache-2.0$q$, $q$https://github.com/falcosecurity/falco$q$),
  ($q$osquery$q$, $q$osquery$q$, $q$defense$q$, $q$Lets you ask questions about a machine with SQL: processes, users, ports, installed software. Good for inventory and hunting.$q$, $q$بتسأل الجهاز بـ SQL: العمليات واليوزرز والبورتات والبرامج. كويس للجرد والـ hunting.$q$, array[$q$osqueryi$q$, $q$SELECT name, pid FROM processes LIMIT 5;$q$, $q$.tables$q$]::text[], $q$The osquery project$q$, $q$Apache-2.0 or GPL-2.0 (your choice)$q$, $q$https://github.com/osquery/osquery$q$),
  ($q$semgrep$q$, $q$Semgrep$q$, $q$defense$q$, $q$Static code analysis with readable rules. Scan a project with the auto config or a ruleset, and export JSON.$q$, $q$تحليل كود ثابت بقواعد سهلة القراءة. بتفحص مشروع بالـ config التلقائي أو مجموعة قواعد وتصدر JSON.$q$, array[$q$semgrep scan --config auto$q$, $q$semgrep --config p/owasp-top-ten .$q$, $q$semgrep scan --json -o out.json$q$]::text[], $q$Semgrep, Inc.$q$, $q$LGPL-2.1$q$, $q$https://github.com/semgrep/semgrep$q$),
  ($q$grype$q$, $q$Grype$q$, $q$defense$q$, $q$Vulnerability scanner for container images and folders. Reads an image, directory or SBOM and lists known CVEs.$q$, $q$ماسح ثغرات لصور الـ containers والمجلدات. بيقرا صورة أو مجلد أو SBOM ويعرض الـ CVEs المعروفة.$q$, array[$q$grype alpine:latest$q$, $q$grype dir:.$q$, $q$grype sbom:./sbom.json$q$]::text[], $q$Anchore$q$, $q$Apache-2.0$q$, $q$https://github.com/anchore/grype$q$),
  ($q$syft$q$, $q$Syft$q$, $q$defense$q$, $q$Generates a software bill of materials (SBOM) from images and folders, in SPDX or CycloneDX. Pairs with Grype.$q$, $q$بيطلع SBOM (قائمة مكونات البرنامج) من صور ومجلدات بصيغة SPDX أو CycloneDX. بيشتغل مع Grype.$q$, array[$q$syft alpine:latest$q$, $q$syft dir:. -o spdx-json$q$, $q$syft alpine:latest -o cyclonedx-json$q$]::text[], $q$Anchore$q$, $q$Apache-2.0$q$, $q$https://github.com/anchore/syft$q$),
  ($q$crowdsec$q$, $q$CrowdSec$q$, $q$defense$q$, $q$Open-source security engine that detects attacks from logs and blocks bad IPs, sharing signals with a community.$q$, $q$محرك أمان مفتوح المصدر بيكتشف الهجمات من اللوجات ويحظر IPs وحشة، وبيشارك الاشارات مع مجتمع.$q$, array[$q$cscli decisions list$q$, $q$cscli collections install crowdsecurity/nginx$q$, $q$cscli metrics$q$]::text[], $q$CrowdSec$q$, $q$MIT$q$, $q$https://github.com/crowdsecurity/crowdsec$q$),
  ($q$frida$q$, $q$Frida$q$, $q$mobile$q$, $q$Dynamic instrumentation toolkit. Inject scripts into running apps on Android, iOS and desktop to inspect and trace behaviour. Use it only on systems you own or have written permission to test.$q$, $q$أداة dynamic instrumentation. بتحقن سكريبتات في تطبيقات شغالة على أندرويد وiOS وسطح المكتب عشان تراقب وتتبع السلوك. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$frida-ps -U$q$, $q$frida -U -f com.example.app$q$, $q$frida-trace -U -i open com.example.app$q$]::text[], $q$Ole Andre V. Ravnas and the Frida project$q$, $q$wxWindows Library Licence 3.1$q$, $q$https://github.com/frida/frida$q$),
  ($q$apktool$q$, $q$Apktool$q$, $q$mobile$q$, $q$Decodes Android APK resources and smali code, and rebuilds the APK after changes. Use on apps you may analyse.$q$, $q$بيفك موارد وكود smali لتطبيقات أندرويد APK ويعيد بناءه بعد التعديل. استخدمه على تطبيقات مسموح لك تحللها.$q$, array[$q$apktool d app.apk$q$, $q$apktool d -f app.apk -o out$q$, $q$apktool b out -o new.apk$q$]::text[], $q$Connor Tumbleson (iBotPeaches)$q$, $q$Apache-2.0$q$, $q$https://github.com/iBotPeaches/Apktool$q$),
  ($q$jadx$q$, $q$jadx$q$, $q$mobile$q$, $q$Decompiles Android APK and DEX files to readable Java code. Has a command line tool and a GUI.$q$, $q$بيحوّل ملفات APK وDEX لكود Java مقروء. فيه أداة سطر أوامر وواجهة رسومية.$q$, array[$q$jadx app.apk$q$, $q$jadx -d out app.apk$q$, $q$jadx-gui app.apk$q$]::text[], $q$skylot$q$, $q$Apache-2.0$q$, $q$https://github.com/skylot/jadx$q$),
  ($q$objection$q$, $q$Objection$q$, $q$mobile$q$, $q$Runtime mobile exploration toolkit built on Frida. Attach to an app and test things like SSL pinning without a jailbreak. Use it only on systems you own or have written permission to test.$q$, $q$أداة استكشاف تطبيقات موبايل وقت التشغيل مبنية على Frida. بتتصل بتطبيق وتختبر حاجات زي SSL pinning من غير jailbreak. استخدمها بس على أنظمة بتملكها أو معاك إذن كتابي بفحصها.$q$, array[$q$objection -g com.example.app explore$q$, $q$android sslpinning disable$q$, $q$ios sslpinning disable$q$]::text[], $q$SensePost$q$, $q$GPL-3.0$q$, $q$https://github.com/sensepost/objection$q$),
  ($q$opencti$q$, $q$OpenCTI$q$, $q$platform$q$, $q$Platform to store, organise and share cyber threat intelligence as a knowledge graph. Connect feeds, then search indicators and reports.$q$, $q$منصة لتخزين وتنظيم ومشاركة معلومات التهديدات السيبرانية كـ knowledge graph. بتوصل feeds وبعدين تبحث في المؤشرات والتقارير.$q$, array[$q$docker compose up -d (see the official docker repo)$q$]::text[], $q$Filigran and the OpenCTI community$q$, $q$Apache-2.0 (Community Edition)$q$, $q$https://github.com/OpenCTI-Platform/opencti$q$)
